SELECT MONTH(c.signup_date) AS signup_month, CASE WHEN c.credit_limit >= 14100 THEN 'high' WHEN c.credit_limit >= 6500 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, SUM(CASE WHEN s.carrier = 'Kerry' THEN 1 ELSE 0 END) AS kerry_count, ROUND(AVG(s.cost), 2) AS avg_cost FROM shipments s RIGHT JOIN orders o ON s.order_id = o.id LEFT JOIN customers c ON o.customer_id = c.id GROUP BY MONTH(c.signup_date), CASE WHEN c.credit_limit >= 14100 THEN 'high' WHEN c.credit_limit >= 6500 THEN 'mid' ELSE 'low' END;
